def count_unique_keys(t):
    unique_keys = {}
    for i, value in enumerate(t):
        if value not in unique_keys:
            unique_keys[value] = [i]
        else:
            unique_keys[value].append(i)
    return {key: len(value) for key, value in unique_keys.items()}
```

