def is_gregorian_date_valid(year, month, day):
    if month < 1 or month > 12:
        return False
    if day < 1:
        return False
    if month in [1, 3, 5, 7, 8, 10, 12]:
        max_days = 31
    elif month == 2:
        if (year % 4 == 0 and year % 100 != 0) or year % 400 == 0:
            max_days = 29
        else:
            max_days = 28
    else:
        max_days = 30
    if day > max_days:
        return False
    return True
```
