```python
def sum_first_even_odd(numbers):
    first_even = None
    first_odd = None
    for num in numbers:
        if num % 2 == 0 and first_even is None:
            first_even = num
        elif num % 2 != 0 and first_odd is None:
            first_odd = num
        if first_even is not None and first_odd is not None:
            break
    if first_even is not None and first_odd is not None:
        return first_even + first_odd
    elif first_even is not None:
        return first_even
    elif first_odd is not None:
        return first_odd
    else:
        return 0
```

